import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
def nz(X):
    Z=(X-X.mean(0))/(X.std(0)+1e-6); return Z/np.linalg.norm(Z,axis=1,keepdims=True)
def zsc(X): return (X-X.mean(0))/(X.std(0)+1e-6)/np.sqrt(X.shape[1])
def kcv(K, lam=1e-2, seeds=(0,1,2)):
    out=[]
    for s in seeds:
        f=folds(y,5,s); S=np.zeros((len(y),8))
        for i in range(5):
            tr=f!=i; te=f==i
            A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[te]=K[np.ix_(te,tr)]@A
        out.append((S.argmax(1)==y).mean())
    return round(float(np.mean(out)),4)
q=lambda C: C+0.5*C**2
Gn={L: nz(M(L))@nz(M(L)).T for L in range(13)}
Gl={L: zsc(M(L))@zsc(M(L)).T for L in range(13)}
for j in range(4,13):
    r=[kcv(q(Gn[j]))]
    for c in [0.3,1.0]:
        r.append(kcv(q(Gn[j])+c*Gl[1]))
    r.append(kcv(q(Gn[j])+0.5*(Gl[1]+Gl[j//2])))
    print(j, 'kern Mj', r[0], ' +lin M1 c.3/1', r[1], r[2], ' +lin M1,M_j/2', r[3])
